void expect(dynamic a, dynamic b) {
  if (a == b) return;

  if (a is List && b is List) {
    expectList(a, b);
  } else if (a is Map && b is Map) {
    expectMap(a, b);
  } else if (a is Set && b is Set) {
    expectSet(a, b);
  } else {
    throw '$a != $b';
  }
}

